import json
from django.views import View
from django.http import JsonResponse, HttpResponseForbidden, HttpResponseNotFound
from .models import CloudAssetInventory

class AssetHStoreAttributesUpdateView(View):
    def patch(self, request, asset_id):
        if not request.user.is_authenticated:
            return HttpResponseForbidden("Authentication required")

        data = json.loads(request.body)
        new_attrs = data.get("custom_tags", {})

        # Scope asset lookup to authenticated user's customer account
        asset = CloudAssetInventory.objects.filter(id=asset_id, customer_account=request.user.customer_account).first()
        if not asset:
            return HttpResponseNotFound("Asset not found")

        asset.custom_tags.update(new_attrs)
        asset.save(update_fields=['custom_tags'])
        return JsonResponse({"asset_id": asset.id, "custom_tags": asset.custom_tags})
